DataflowSourceRule.Script:
var newPattern = "";
for each (var input in program.struts1Inputs) {
  if (null == newPattern.match(input.property) && (null != input.property || 0 != input.property.length)) {
    if (newPattern != "") {
      newPattern = newPattern + "|" + input.property;
    }
    else {
      newPattern = input.property;
    }
  }
}
if (null != newPattern && 0 != newPattern.length) {
  rule.FunctionIdentifier.NamespaceName.Value ="org.apache.commons.beanutils";
  rule.FunctionIdentifier.ClassName.Value = "PropertyUtils";
  rule.FunctionIdentifier.FunctionName.Pattern = "getProperty|getIndexedProperty|getMappedProperty|getNestedProperty|getSimpleProperty";
  rule.Conditional.ConstantMatches.Pattern = newPattern;
}

var newPattern = "";
for each (var input in program.struts1PrivateInputs) {
  if (null == newPattern.match(input.property) && (null != input.property || 0 != input.property.length)) {
    if (newPattern != "") {
      newPattern = newPattern + "|" + input.property;
    }
    else {
      newPattern = input.property;
    }
  }
}
if (null != newPattern && 0 != newPattern.length) {
  rule.FunctionIdentifier.NamespaceName.Value ="org.apache.commons.beanutils";
  rule.FunctionIdentifier.ClassName.Value = "PropertyUtils";
  rule.FunctionIdentifier.FunctionName.Pattern = "getProperty|getIndexedProperty|getMappedProperty|getNestedProperty|getSimpleProperty";
  rule.Conditional.ConstantMatches.Pattern = newPattern;
}

// iterate over the dwr sources (scripted objects and spring and jsf beans)
// do not iterate over newed objects and remoted spring beans because they seem to only be relevant for entrypoints
// do not iterate over struts beans because we already generate source rules for their getters
function generateDWRSourceRule(sourcekind) {
  for each (var s in sourcekind) {
    // do not iterate over newed objects and remoted spring beans because they seem to only be relevant for entrypoints
    // do not iterate over struts and jsf beans because we already generate source rules for their getters
    if (((s.creator == "script" || s.creator == "spring" || s.creator == "jsf") && null == s.dwrRemote)) {
      var namespaceN = "";
      var classN = "";
      var functionN = "";
      var functionNE = "";

      // generate namespace name
      if (null == namespaceN.match(s.namespaceName)) {
        if (namespaceN != "") {
          namespaceN = namespaceN + "|" + s.namespaceName;
        }
        else {
          namespaceN = s.namespaceName;
        }
      }

      // generate class name
      if (null == classN.match(s.className)) {
        if (classN != "") {
          classN = classN + "|" + s.className;
        }
        else {
          classN = s.className;
        }
      }

      // generate function names to be included in the rule
      for each (var f in s.functionNamesInclude) {
        if (-1 == functionN.indexOf(f)) {
          if (functionN != "") {
            functionN = functionN + "|" + f;
          }
          else {
            functionN = f;
          }
        }
      }

      // generate function names to be excluded from the rule
      for each (var f in s.functionNamesExclude) {
        if (null == functionNE.match(f)) {
          if (functionNE != "") {
            functionNE = functionNE + "|" + f;
          }
          else {
            functionNE = f;
          }
        }
      }

      // append another function identifier when needed
      if (counterForDWRSource > 0) {
        rule.appendChild(new XML(spareFunctionIdentifierSource));
      }

      // set the fields of the function identifier, if there are values to be set
      if (0 < namespaceN.length && 0 < classN.length && 0 < functionN.length) {
        rule.FunctionIdentifier[counterForDWRSource].NamespaceName.Pattern = namespaceN;
        rule.FunctionIdentifier[counterForDWRSource].ClassName.Pattern = classN;
        rule.FunctionIdentifier[counterForDWRSource].FunctionName.Pattern = functionN;
      }

      // generate <Except/> clause if we have a list of functions to be excluded from the rule
      if (0 < functionNE.length) {
        rule.FunctionIdentifier[counterForDWRSource].Except.FunctionIdentifier.NamespaceName.Pattern = namespaceN;
        rule.FunctionIdentifier[counterForDWRSource].Except.FunctionIdentifier.ClassName.Pattern = classN;
        rule.FunctionIdentifier[counterForDWRSource].Except.FunctionIdentifier.FunctionName.Pattern = functionNE;
        rule.FunctionIdentifier[counterForDWRSource].Except.FunctionIdentifier.ApplyTo["@implements"] = "true";
        rule.FunctionIdentifier[counterForDWRSource].Except.FunctionIdentifier.ApplyTo["@overrides"] = "true";
        rule.FunctionIdentifier[counterForDWRSource].Except.FunctionIdentifier.ApplyTo["@extends"] = "true";
      }

      counterForDWRSource++;
    }
  }
}

var counterForDWRSource = 0;
// save a template for adding more function identifiers
var spareFunctionIdentifierSource = rule.FunctionIdentifier[0].toXMLString();

generateDWRSourceRule(program.dwrSources);
generateDWRSourceRule(program.spring_beans);

//alert("\n******************************\n");
//alert(rule);
//alert("\n******************************\n");

DataflowEntryPointRule.Script:
// iterate over all the dwr sources (newed and scripted object, and spring, struts, and jsf beans)
// as well as spring beans that are remoted with dwr namespace handler
function generateDWREntryPointRule(sourcekind) {
  for each (var s in sourcekind) {
    // null == dwrRemote means we're dealing with program.dwrSources
    // true == dwrRemote means we're dealing with remoted spring beans
    // we need this check because we do not want to include spring beans that are not remoted
    if (null == s.dwrRemote || true == s.dwrRemote) {
      var namespaceN = "";
      var classN = "";
      var functionN = "";
      var functionNE = "";

      // generate namespace name
      if (null == namespaceN.match(s.namespaceName)) {
        if (namespaceN != "") {
          namespaceN = namespaceN + "|" + s.namespaceName;
        }
        else {
          namespaceN = s.namespaceName;
        }
      }

      // generate class name
      if (null == classN.match(s.className)) {
        if (classN != "") {
          classN = classN + "|" + s.className;
        }
        else {
          classN = s.className;
        }
      }

      // generate function names to be included in the rule
      for each (var f in s.functionNamesInclude) {
        if (-1 == functionN.indexOf(f)) {
          if (functionN != "") {
            functionN = functionN + "|" + f;
          }
          else {
            functionN = f;
          }
        }
      }

      // generate function names to be excluded from the rule
      for each (var f in s.functionNamesExclude) {
        if (null == functionNE.match(f)) {
          if (functionNE != "") {
            functionNE = functionNE + "|" + f;
          }
          else {
            functionNE = f;
          }
        }
      }

      // append another function identifier when needed
      if (counterForDWR > 0) {
        rule.appendChild(new XML(spareFunctionIdentifier));
      }

      // set the fields of the function identifier, if there are values to be set
      if (0 < namespaceN.length && 0 < classN.length && 0 < functionN.length) {
        rule.FunctionIdentifier[counterForDWR].NamespaceName.Pattern = namespaceN;
        rule.FunctionIdentifier[counterForDWR].ClassName.Pattern = classN;
        rule.FunctionIdentifier[counterForDWR].FunctionName.Pattern = functionN;
      }

      // generate <Except/> clause if we have a list of functions to be excluded from the rule
      if (0 < functionNE.length) {
        rule.FunctionIdentifier[counterForDWR].Except.FunctionIdentifier.NamespaceName.Pattern = namespaceN;
        rule.FunctionIdentifier[counterForDWR].Except.FunctionIdentifier.ClassName.Pattern = classN;
        rule.FunctionIdentifier[counterForDWR].Except.FunctionIdentifier.FunctionName.Pattern = functionNE;
        rule.FunctionIdentifier[counterForDWR].Except.FunctionIdentifier.ApplyTo["@implements"] = "true";
        rule.FunctionIdentifier[counterForDWR].Except.FunctionIdentifier.ApplyTo["@overrides"] = "true";
        rule.FunctionIdentifier[counterForDWR].Except.FunctionIdentifier.ApplyTo["@extends"] = "true";
      }
      counterForDWR++;
    }
  }
}

var counterForDWR = 0;
// save a template for adding more function identifiers
var spareFunctionIdentifier = rule.FunctionIdentifier[0].toXMLString();

generateDWREntryPointRule(program.dwrSources);
generateDWREntryPointRule(program.spring_beans);

