StructuralRule.Script:
//
// I think the deal in struts2 is that beans are not singletons by default.
// Further complicating matters, beans do not have to be derived from the struts
// Action base class.  Solution is:
//  - Make a list of singleton classes.  Include Action on the list only if this
//    appears to be a struts1 application.
//  - Add in any beans that have the singleton flag set.
//  - Build up a predicate fragment based on the singleton class names.
//  - Do a text replace on the predicate to insert the fragment.
//

// build list of singleton classes
var singletonNames = new Array();
var singletonClassCount = 0;
function addSingletonClass(name) {
  for each (var foo in singletonNames) {
    if (foo == name || null == name || 0 == name.length) {
      return;
    }
  }
  singletonNames[singletonClassCount++] = name;
}
if (program.struts_beans.length == 0) {
  // if no beans declared, assume this is struts1 and not struts2
  addSingletonClass("org.apache.struts.action.Action");
}

// create predicate fragment
var namePredicate = "";
for each (var i in singletonNames) {
  if (namePredicate != "") {
    namePredicate += " or ";
  }
  namePredicate += " name == \""+i+"\"\n";
}

// insert fragment into rule
var tmp = String(rule.Predicate);
if (namePredicate == "") {
  namePredicate = "name == \"\"";
}
rule.Predicate = String(rule.Predicate).replace(/PUT_SINGLETON_CLASS_NAMES_HERE/, namePredicate);

StructuralRule.Predicate:
AssignmentStatement: lhs.location is
                [FieldAccess: instance.location is [VariableAccess: this] and field is [Field dec:]*] and
                enclosingClass.supers contains [Class: PUT_SINGLETON_CLASS_NAMES_HERE] and
                not enclosingFunction is
                        /* EXCEPTION: enclosing function is a constructor or its name starts with "init" */
                        [constructor or name matches "init.*" or
                        /* EXCEPTION: enclosing function is only reachable from a constructor */
                        (not public and not protected and (callers.length == 0 or callers contains [constructor]) and not callers contains [not constructor]) or
                        /* EXCEPTION: enclosing function starts with "set" and is not reachable from any of the non-constructor functions */
                        (name matches "set.*" and not callers contains [not constructor]) or
                        /* EXCEPTION: callers of enclosing function do not contain any functions other than init() */
                        (callers.length != 0 and not callers contains [Function: not name matches "init.*"])
                ] and
                /* EXCEPTION: value assigned is immutable (final) */
                not rhs.location is [VariableAccess: variable.final] and
                not rhs.location is [FieldAccess: field.final]

StructuralRule.Script:
//
// I think the deal in struts2 is that beans are not singletons by default.
// Further complicating matters, beans do not have to be derived from the struts
// Action base class.  Solution is:
//  - Make a list of singleton classes.  Include Action on the list only if this
//    appears to be a struts1 application.
//  - Add in any beans that have the singleton flag set.
//  - Build up a predicate fragment based on the singleton class names.
//  - Do a text replace on the predicate to insert the fragment.
//

// build list of singleton classes
var singletonNames = new Array();
var singletonClassCount = 0;
function addSingletonClass(name) {
  for each (var foo in singletonNames) {
    if (foo == name || null == name || 0 == name.length) {
      return;
    }
  }
  singletonNames[singletonClassCount++] = name;
}

// add in singleton beans
for each (var bean in program.struts_beans) {
  if (bean.singleton) {
    addSingletonClass(bean.clss);
  }
}

// create predicate fragment
var namePredicate = "";
for each (var i in singletonNames) {
  if (namePredicate != "") {
    namePredicate += " or ";
  }
  namePredicate += " name == \""+i+"\"\n";
}

// insert fragment into rule
var tmp = String(rule.Predicate);
if (namePredicate == "") {
  namePredicate = "name == \"\"";
}
rule.Predicate = String(rule.Predicate).replace(/PUT_SINGLETON_CLASS_NAMES_HERE/, namePredicate);

StructuralRule.Predicate:
AssignmentStatement: lhs.location is
                [FieldAccess: instance.location is [VariableAccess: this] and field is [Field dec:]*] and
                enclosingClass.supers contains [Class: PUT_SINGLETON_CLASS_NAMES_HERE] and
                not enclosingFunction is
                        /* EXCEPTION: enclosing function is a constructor or its name starts with "init" */
                        [constructor or name matches "init.*" or
                        /* EXCEPTION: enclosing function is only reachable from a constructor */
                        (not public and not protected and (callers.length == 0 or callers contains [constructor]) and not callers contains [not constructor]) or
                        /* EXCEPTION: enclosing function starts with "set" and is not reachable from any of the non-constructor functions */
                        (name matches "set.*" and not callers contains [not constructor]) or
                        /* EXCEPTION: callers of enclosing function do not contain any functions other than init() */
                        (callers.length != 0 and not callers contains [Function: not name matches "init.*"])
                ] and
                /* EXCEPTION: value assigned is immutable (final) */
                not rhs.location is [VariableAccess: variable.final] and
                not rhs.location is [FieldAccess: field.final]
                and enclosingFunction.callers.length > 1

StructuralRule.Script:
 var field = "";
 var found = false;
 var thisResult = null;
 var results = new Array();
 for each (var a in program.struts1_actions) {
   if (0 != a.name.length) {
     var bean = program.form_beans[a.name];
     if (null != bean) {
       for each (var v in program.validation_forms) {
         if (null != v) {
           // for ValidatorForm and DynaValidatorForm, look up by name, for ValidatorActionForm and DynaValidatorActionForm, look up by path
           // for non Validator forms, report based on the path
           if (((true == bean.vaf || true == bean.dvaf) && a.path == v.name) ||
            (((true == bean.vf && false == bean.vaf) || (true == bean.dvf && false == bean.dvaf)) && a.name == v.name)) {
             if (null != bean.fields && 0 != bean.fields.length) {
               for each (var m in bean.fields) {
                 found = false;
                 dbg("field name: " + m.fieldName);
                 if (null != m) {
                   for (var f in v.fields) {
                     if (m.fieldName == f) {
                       found = true;
                     }
                   }
                   if (false == found) {
                     if (null == results[m.className]) {
                       thisResult = new Array();
                     }
                     else {
                       thisResult = results[m.className];
                     }
                     thisResult[thisResult.length] = "set" + m.fieldName.substr(0, 1).toUpperCase() + m.fieldName.substr(1);
                     results[m.className] = thisResult;
                     dbg("extra field's setter: " + "set" + m.fieldName.substr(0, 1).toUpperCase() + m.fieldName.substr(1));
                   }
                 }
               }
             }
           }
         }
       }
     }
   }
 }

// create predicate fragment
var namePredicate = "";
var outerCounter = 0;
var innerCounter = 0;

for (var c in results) {
  if (namePredicate != "") {
    namePredicate += " or ";
  }
  dbg("c: " + c);
  namePredicate += " (fa.enclosingClass.name == \"" + c + "\"";
  if (null != results[c] && 0 != results[c].length) {
    innerCounter = 0;
    for each (var f in results[c]) {
      if (0 == innerCounter) {
        namePredicate += " and (";
      }
      else if (0 != innerCounter) {
        namePredicate += " or";
      }
      namePredicate += " fa.enclosingFunction.name == \"" + f + "\"";
      innerCounter++;
    }
    namePredicate += "))\n";
  }
  outerCounter++;
}

if (0 == outerCounter || 0 == namePredicate.length) {
  namePredicate = "fa.field.name matches \"\"\n";
}
else {
  namePredicate = "(" + namePredicate + ") and fa.field is [Field f: ]*";
}

// insert fragment into rule
var tmp = String(rule.Predicate);
rule.Predicate = String(rule.Predicate).replace(/PUT_FORM_FIELD_NAMES_HERE/g, namePredicate);

dbg("***************");
dbg(rule);
dbg("******************");

// get the list of names of all scanned xml files
var xmlFiles = getXMLConfigFileNames();

// build list of unvalidated action classes
var unvalidatedActionClassNames = new Array();
var unvalidatedActionClassCount = 0;
function addUnvalidatedActionClass(name) {
  for each (var foo in unvalidatedActionClassNames) {
    if (foo == name || null == name || 0 == name.length) {
      return;
    }
  }
  unvalidatedActionClassNames[unvalidatedActionClassCount++] = name;
}

// add in unvalidated action class names
for each (var act in program.struts_actions) {
  var unvalidated = true;
  for each (var fileName in xmlFiles) {
    if (fileName.match(act.className) && fileName.match("validation.xml")) {
      unvalidated = false;
      break;
    }
  }
  if (true == unvalidated) {
    addUnvalidatedActionClass(act.clss);
  }
}

// create predicate fragment
var namePredicate = "";
for each (var i in unvalidatedActionClassNames) {
  if (namePredicate != "") {
    namePredicate += " or ";
  }
  namePredicate += " name == \""+i+"\"\n";
}
if (0 == unvalidatedActionClassNames.length) {
  namePredicate = "name == \"\""
}
else if (1 < unvalidatedActionClassNames.length) {
  namePredicate = "( " + namePredicate + " )";
}

// insert fragment into rule
var tmp = String(rule.Predicate);
rule.Predicate = String(rule.Predicate).replace(/PUT_ACTION_CLASS_NAMES_HERE/, namePredicate);

// get the list of names of all scanned xml files
var xmlFiles = getXMLConfigFileNames();

// build list of unvalidated action classes
var duplicateActionClassNames = new Array();
var duplicateActionClassCount = 0;
function addDuplicateActionClass(name) {
  for each (var foo in duplicateActionClassNames) {
    if (foo == name || null == name || 0 == name.length) {
      return;
    }
  }
  duplicateActionClassNames[duplicateActionClassCount++] = name;
}

// add in action class names that have multiple <action>-validation.xml files associated with them
  for each (var act in program.struts_actions) {
    var multiple = false;
    var haveSeenOnce = false;
    for each (var fileName in xmlFiles) {
      if (fileName.match(act.className + "-validation.xml")) {
        if (false == haveSeenOnce) {
          haveSeenOnce = true;
        }
        else {
          multiple = true;
          break;
        }
      }
    }
    if (true == multiple) {
      addDuplicateActionClass(act.clss);
    }
  }

// create predicate fragment
var nameDuplicatePredicate = "";
for each (var i in duplicateActionClassNames) {
  if (nameDuplicatePredicate != "") {
    nameDuplicatePredicate += " or ";
  }
  nameDuplicatePredicate += " name == \""+i+"\"\n";
}
if (0 == duplicateActionClassNames.length) {
  nameDuplicatePredicate = "name == \"\"";
}

// insert fragment into rule
var tmpDuplicate = String(rule.Predicate);
rule.Predicate = String(rule.Predicate).replace(/PUT_DUPLICATE_ACTION_CLASS_NAMES_HERE/, nameDuplicatePredicate);

               // get the list of names of all scanned xml files
               var xmlFiles = getXMLConfigFileNames();

               // build a list of results
               var results = new Array();

               // checks whether we already looked at this action class
               function doResultsContain(name) {
                 for each (var i in results) {
                   if (i.clss == name) {
                     return true;
                   }
                 }
                 return false;
               }

               default xml namespace = new Namespace("");
               var fieldns = new Namespace("");

               // add in validated action field names
               for each (var act in program.struts_actions) {
                 if (false == doResultsContain(act.clss)) {
                   for each (var fileName in xmlFiles) {
                     var shortFileName = "";
                     if (-1 != fileName.lastIndexOf("/")) {
                       shortFileName = fileName.substring(fileName.lastIndexOf("/")+1);
                     }
                     else {
                       shortFileName = fileName.substring(fileName.lastIndexOf("\\")+1);
                     }
                     if (shortFileName.startsWith(act.className) && shortFileName.match("validation.xml")) {
                       var result = new Object();
                       result.fields = new Array();
                       result.clss = act.clss;
//alert("FILES MATCHED: " + fileName);
                       try {
                         var validationFile = new XML(readFile(fileName));
//alert("STUFF: " + validationFile..fieldns::field);
                         for each (var j in validationFile..fieldns::field) {
//alert("ADDING: " + String(j["@name"]));
                           result.fields[result.fields.length] = String(j["@name"]);
                         }
//alert ("foo: " + validationFile..fieldns::validator.fieldns::param.(@name == "fieldName"));
                         for each (var j in validationFile..fieldns::validator.fieldns::param.(@name == "fieldName")) {
                           result.fields[result.fields.length] = String(j);
                         }
//alert("ADDING: " + result);
                         results[results.length] = result;
                       }
                       catch (err) {
                         // actively ignoring XML parsing errors. Not much help to customers. See bug 31939 for more details.  
                         // warn_internal(fileName + ": " + err);
                       }
                     }
                   }
                 }
               }

               default xml namespace = new Namespace("xmlns://www.fortifysoftware.com/schema/rules");

               // create predicate fragment
               var namePredicate = "";

               for each (var i in results) {
                 if (namePredicate != "") {
                   namePredicate += " or ";
                 }
