// create predicate fragment
var namePredicate = "";
for each (var act in program.struts_actions) {
    var subPredicate = "";
    var methodlist = "";
    var actionClass = nameTable.getClassByName("", act.clss, "java");
    if (null != actionClass && '[UnknownType]' != actionClass.getName()) {
        var actionClassFields = actionClass.getFields();
        var actionClassMethods = actionClass.getMethods();
        if (null != actionClassFields) {
            for (var i = 0; i < actionClassFields.length; i++) {
                if (null != actionClassFields[i]) {
                    var fieldName = String(actionClassFields[i].getName());
                    for (var j = 0; j < actionClassMethods.length; j++) {
                        var methodName = String(actionClassMethods[j].getName());
                        if (methodName == "get" + fieldName.substr(0, 1).toUpperCase() + fieldName.substr(1)) {
                            if (methodlist != "") {
                                methodlist += "|" + methodName;
                            } else {
                                methodlist = methodName;
                            }
                        }
                    }
                }
            }
        }
    }
    if (methodlist != "" && act.clss) {
        subPredicate = "(";
        subPredicate += "not f.name matches \"" + methodlist + "\" and ";
        subPredicate += " f.enclosingClass is [Class: name == \"" + act.clss + "\"]";
        subPredicate += ")";

        if (namePredicate != "") {
            namePredicate += " or " + subPredicate + "\n";
        } else {
            namePredicate = subPredicate + "\n";
        }
    }
}
if (namePredicate != "") {
    namePredicate = " and (\n" + namePredicate + "\n)";
}
if (namePredicate == "") namePredicate = ' and f.name == "FORTIFY_NON_EXISTANT"';
// insert fragment into rule
var tmp = String(rule.Predicate);
rule.Predicate = String(rule.Predicate).replace(/PUT_PREDICATE_HERE/, String(namePredicate));

StructuralRule.Predicate:
Field f: private and not (static and final and f.type.name == "long" and f.name == "serialVersionUID")
        and not enclosingClass contains
            [Function: reachedBy [Function: not private] and contains [FieldAccess: field == f]]
        /* accounted for nested class variant of above */
        and not enclosingClass contains [Class: contains
            [Function: reachedBy [Function: not private] and contains [FieldAccess: field == f]]
        ]
        /* class declared as field and its function invoked  */
        and not enclosingClass contains
            [Function: contains [FunctionCall: instance is [FieldAccess: field == f ]]]
        /* accounted for nested class variant of above */
        and not enclosingClass contains [Class: contains
            [Function: contains [FunctionCall: instance is [FieldAccess: field == f ]]]
        ]
        /* exclude fields inside Lambda function */
        and not enclosingClass.supers contains [Class: name == "java.util.function.Function"]

Function f: exceptionTypes contains [Type e:
(e.name == "java.lang.Exception" or e.name == "java.lang.Throwable")
and not (f.name == "finalize" and f.parameterTypes.length == 0)
and f.name != "main"
and not (f.enclosingClass.supers contains
    /* only report this on the top class in the hierarchy */
    [Class c: c != f.enclosingClass and contains
        [ Function t: t.name == f.name and t.parameterTypes == f.parameterTypes
          and f.exceptionTypes contains e
        ]
    ]
)
]

IfStatement ifs: in [SynchronizedBlock: in
    [IfStatement: expression == ifs.expression]*
]*
and not ifs contains [AssignmentStatement as:
    as.lhs is [FieldAccess fa: fa.field.volatile]
]

Function:
                /* the function is actually called */
                callers.length == 0 and

                /* equals */
                (((name == "equal" or
          (name == "equals" and (parameterTypes.length != 1 or
              parameterTypes[0].name != "java.lang.Object") and not static)) and
                      /* enclosing class doesn't cntain equals function with expected signature */
                      (not enclosingClass contains [Function: name == "equals" and parameterTypes.length == 1
                                                    and parameterTypes[0].name == "java.lang.Object"])) or
                /* hashCode */
                ((name == "hashcode" or (name == "hashCode" and parameterTypes.length != 0)) and
                      /* enclosing class doesn't contain hashCode function with expected signature */
                      (not enclosingClass contains [Function: name == "hashCode" and parameterTypes.length == 0])) or
                /* toString */
                (name == "tostring" and
                      /* enclsing class doesn't contain toString function with expected signature */
                      not enclosingClass contains [Function: name == "toString"]) or
                /* finalize */
                (name == "finalize" and parameterTypes.length != 0 and
                      /* enclsing class doesn't contain finalize function with expected signature */
                      not enclosingClass contains [Function: name == "finalize" and parameterTypes.length == 0]))

StructuralRule.Script:
// build list of singleton classes
var singletonNames = new Array();
var singletonClassCount = 0;

function addSingletonClass(name) {
  for each (var existing in singletonNames) {
    if (existing == name || null == name || 0 == name.length) {
      return;
    }
  }
  singletonNames[singletonClassCount++] = name;
}

// add in singleton beans
if (program.spring_beans.length > 0) {
  for each (var bean in program.spring_beans) {
    if (bean.isSingleton || bean.isApplicationScoped) {
      addSingletonClass(bean.clss);
    }
  }
}
// create predicate fragment
var namePredicate = "";
for each (var i in singletonNames) {
  if (namePredicate != "") {
    namePredicate += " or ";
  }
  namePredicate += " name == \""+i+"\"\n";
}
// insert fragment into rule
if (namePredicate == "") {
  namePredicate = "name == \"\"";
}
rule.Predicate = String(rule.Predicate).replace(/PUT_SINGLETON_CLASS_NAMES_HERE/, namePredicate);

StructuralRule.Predicate:
AssignmentStatement: lhs.location is [FieldAccess: instance.location is [VariableAccess: this] and field is [Field dec:]*]
        and (
            enclosingClass is [Class: PUT_SINGLETON_CLASS_NAMES_HERE ]
            or enclosingClass.labels contains "SpringSingletonBean"
        ) and not enclosingClass.annotations contains [Annotation:
            type.name == "org.springframework.context.annotation.Scope"
            and elements contains [AnnotationElement:
                value matches "(?i)request|prototype|session|globalsession"
            ]
        ] and not enclosingClass.supers contains [Class:
            name == "org.springframework.web.servlet.mvc.Controller"
            or name == "org.springframework.web.portlet.mvc.Controller"
        ] and not enclosingClass.supers contains [Class: annotations contains [Annotation:
            type.name == "org.springframework.stereotype.Controller"
            or type.name == "org.springframework.web.bind.annotation.RestController"
        ]]
        and not enclosingFunction is
                /* EXCEPTION: enclosing function is a constructor or its name starts with "init" */
                [constructor or name matches "init.*" or
                /* EXCEPTION: enclosing function is only reachable from a constructor */
                (not public and not protected and (callers.length == 0 or callers contains [constructor]) and not callers contains [not constructor]) or
                /* EXCEPTION: enclosing function starts with "set" and is not reachable from any of the non-constructor functions */
                (name matches "set.*" and not callers contains [not constructor]) or
                /* EXCEPTION: callers of enclosing function do not contain any functions other than init() */
                (callers.length != 0 and not callers contains [Function: not name matches "init.*"]) or
                /* EXCEPTION:  org.springframework.beans.factory.InitializingBean.afterPropertiesSet is only call once*/
                (name == "afterPropertiesSet" and enclosingClass.supers contains [Class ibean: name == "org.springframework.beans.factory.InitializingBean"]) or
                /* EXCEPTION: org.springframework.beans.factory.DisposableBean.destroy is only call once */
                (name == "destroy" and enclosingClass.supers contains [Class dbean: name == "org.springframework.beans.factory.DisposableBean"])]
        and enclosingFunction.callers.length > 1

