            or (not public and not protected and (callers.length == 0 or callers contains [constructor]) and not callers contains [not constructor])
            /* EXCEPTION:  org.springframework.beans.factory.InitializingBean.afterPropertiesSet is only call once*/
            or (name == "afterPropertiesSet" and enclosingClass.supers contains [Class ibean: name == "org.springframework.beans.factory.InitializingBean"])
