            or (name == "destroy" and enclosingClass.supers contains [Class dbean: name == "org.springframework.beans.factory.DisposableBean"])
            /* EXCEPTION: @PostConstruct and @PreDestroy methods are only called once */
            or (annotations contains [type.name matches "javax.annotation.(PostConstruct|PreDestroy)"])
            /* EXCEPTION: enclosing function is only reachable from a method that is only called once */
            or (
                callers.length != 0
