FunctionCall fc: (function.constructor or function.name == "init")
    and fc.function.enclosingClass.name matches "org\.springframework\.web\.(servlet|portlet)\.ModelAndView"
    and fc.arguments[0] is [Operation o:
        /* o.op == "+" Bug 4011 */ (o.lhs.constantValue == "redirect:"
        or o.lhs.constantValue == "ajax-redirect:")
    ]

Variable p:
    p.enclosingFunction is [Function f:
        f.parameters contains p
    ]
    and ( p.annotations contains [Annotation:
        type.name matches "javax\.ws\.rs\.(Header|Matrix|Cookie|Query|Path)Param"
    ])
    and (p.annotations contains [Annotation:
        type.name == "javax.ws.rs.Encoded"
    ])

Variable p:
    p.enclosingFunction is [Function f:
        f.parameters contains p
    ]
    and p.annotations contains [Annotation:
        type.name matches "javax\.ws\.rs\.(Header|Matrix|Cookie|Query|Path)Param"
    ]
    and not p.annotations contains [Annotation:
        type.name == "javax.ws.rs.Encoded"
    ]

ReturnStatement rs: rs.expression is [Expression e:]
    /* Web method so bound to GET,POST,PUT,OPTIONS,HEAD or DELETE requests */
    and rs.enclosingFunction.annotations contains [Annotation b: b.type.name matches "javax\.ws\.rs\.(GET|POST|PUT|DELETE|OPTIONS|HEAD)"]
    /* Web Method does produce text/html response */
    and (
        (rs.enclosingFunction.annotations contains [Annotation m: 
            type == T"javax.ws.rs.Produces"
            and elements contains [AnnotationElement: 
                key == "value" 
                and (
                    value matches "(?i)text/html.*"
                    or value matches "(?i)application/xml.*"
                    or value is [ConstantArray: values contains [String: matches "(?i)text/html.*"]]
                    or value is [ConstantArray: values contains [String: matches "(?i)application/xml.*"]]
                )
            ]
        ]) or (
            not rs.enclosingFunction.annotations contains [Annotation: type == T"javax.ws.rs.Produces"]
            and rs.enclosingFunction.enclosingClass.annotations contains [Annotation: 
                type == T"javax.ws.rs.Produces"
                and elements contains [AnnotationElement: 
                    key == "value" 
                    and (
                        value matches "(?i)text/html.*"
                        or value matches "(?i)application/xml.*"
                        or value is [ConstantArray: values contains [String: matches "(?i)text/html.*"]]
                        or value is [ConstantArray: values contains [String: matches "(?i)application/xml.*"]]
                    )
                ]
            ]
        ) or (
            not rs.enclosingFunction.annotations contains [Annotation: type == T"javax.ws.rs.Produces"]
            and not rs.enclosingFunction.enclosingClass.annotations contains [Annotation: type == T"javax.ws.rs.Produces"]
        )
    )
    /* TODO: Only CompletionStage<String> should be reported. Review when bug 37788 is fixed */
    and (enclosingFunction.returnType.name == "java.lang.String"
    or enclosingFunction.returnType.name == "java.util.concurrent.CompletionStage")

CharacterizationRule.Script:
                var template = ") or (call.instance.type.name == \"FORTIFYCLASSSUBSTITUTION\" and call.arguments[0] is [FieldAccess: field.name == \"FORTIFYCLASSMEMBERSUBSTITUTION\"]))";

                for each (var thisInput in program.OA_Inputs) {
                  var thisAM = program.OA_Pages[thisInput.xmlfilename];
                  if (null != thisAM && null != thisAM.VOs) {
                    var thisVO = thisAM.VOs[thisInput.viewName];
                    if (null != thisVO && null != thisVO.ViewAttributes) {
                      var thisAttribute = thisVO.ViewAttributes[thisInput.viewAttr];
                      if (null != thisAttribute) {
                        rule = expandStructuralMatch(template, rule);
                        rule = modifyStructuralMatch(thisVO.rowfullclss, thisAttribute.AliasName, rule);
                        var thisEO = thisVO.EOs[thisAttribute.EntityUsage];
                        if (null != thisEO && null != thisEO.Attributes) {
                          var thisEntityAttribute = thisEO.Attributes[thisAttribute.EntityAttrName];
                          if (null != thisEntityAttribute) {
                            rule = expandStructuralMatch(template, rule);
                            rule = modifyStructuralMatch(thisEO.rowfullclss, thisEntityAttribute.ColumnName, rule);
                          }
                        }
                      }
                    }
                  }
                }
                rule = modifyStructuralMatch("", "", rule);
//alert(rule);

                var template = ") or (rs.enclosingClass.name == \"FORTIFYCLASSSUBSTITUTION\" and rs.enclosingFunction.name == \"FORTIFYCLASSMEMBERSUBSTITUTION\"))";

                for each (var thisOutput in program.OA_Outputs) {
