                            rule = modifyStructuralMatch(thisEO.rowfullclss, "get" + thisEntityAttribute.Name, rule);
                          }
                        }
                      }
                    }
                  }
                }
                rule = modifyStructuralMatch("", "", rule);
//alert(rule);

               var template = ") or (rs.enclosingClass.name == \"FORTIFYCLASSSUBSTITUTION\" and rs.enclosingFunction.name == \"FORTIFYCLASSMEMBERSUBSTITUTION\"))";

               for each (var thisOutput in program.OA_Outputs) {
                  var thisAM = program.OA_Pages[thisOutput.xmlfilename];
