CharacterizationRule.StructuralMatch:
Function f:
    /* look for a function whose enclosing class is public */
    f.enclosingClass.public and
    /*  whose function is public */
    f.public and
    /* that are defined in a file with the JWS extension */
    f.filename matches "(?i).*\.jws$" and
    f.parameters contains [Variable p: ]

CharacterizationRule.Definition:
javax.naming.directory / Attributes.put(key, value) {
    controlflow:
        Escape(escapeArg = value)
}

CharacterizationRule.StructuralMatch:
Function f:
  /* look for a function whose enclosing class implements an interface that */
  f.enclosingClass.supers contains [Class c: c.supers contains
    /*  directly extends "com.google.gwt.user.client.rpc.RemoteService", and */
    [Class c2: c2.name == "com.google.gwt.user.client.rpc.RemoteService"] and
    /* the function we are looking for implements one of the functions in the interface */
    c.functions contains [Function f2: f2 in f.supers]] and
  f.parameters[0] is [Variable param: ]

FunctionCall fc:
    function is [Function:
        name == "of"
        and enclosingClass.supers contains [Class: 
            name == "org.apache.wicket.model.LambdaModel"
        ]
        and parameterTypes.length == 2
    ] 
    and arguments[1] is [Expression setter:
        type.definition is [Class consumer:
            functions contains [Function f:
                name == "innerinit"
                and fc.enclosingFunction contains [FunctionCall:
                    function is f
                    and arguments[0] is [Expression e:]
                ]
            ]
        ]
    ]

FunctionCall:
    function is [Function:
        name matches "append|prepend|newValue|replace"
        and enclosingClass.supers contains [Class:
            name == "org.apache.wicket.AttributeModifier"
        ]
    ]
    and arguments[0].constantValue matches "style|href|cite|action|src|longdesc|on.*"
    and arguments[1] is [Expression e:]

FunctionCall:
