ReturnStatement rs:
    expression is [Expression e:]
    and enclosingFunction is [Function:
        /* Controller method */
        annotations contains [Annotation:
            (
                type.name matches "org\.springframework\.web\.bind\.annotation\.((Request|Get|Post|Delete|Put|Patch)Mapping|ExceptionHandler)"
                or type.definition.labels contains [String s: s == "SPRINGMVC_REQUESTMAPPING_CLASS"]
            )
        ]
    ]
    and enclosingFunction is [Function:
        /* @ReponseBody annotated String */
        annotations contains [Annotation:
            type.name == "org.springframework.web.bind.annotation.ResponseBody"
        ]
        or enclosingClass.annotations contains [Annotation:
            type.name == "org.springframework.web.bind.annotation.RestControllerAdvice"
        ]
        /* String wrappers */
        or returnType.name == "org.springframework.web.context.request.async.DeferredResult"
        or returnType.name == "java.util.concurrent.CompletableFuture"
        or returnType.name == "java.util.concurrent.Callable"
        or returnType.name == "reactor.core.publisher.Flux"
        or returnType.name == "reactor.core.publisher.Mono"
    ]

ReturnStatement rs:
