FunctionCall fc: function is [Function:
        name matches "sendSourceAndReceive|sendAndReceive"
        and enclosingClass.supers contains [Class:
            name == "org.springframework.ws.client.core.WebServiceOperations"
        ]
    ]
    and enclosingStatement is [Statement closure:]
    and arguments contains [Expression lambda:
        /* type.name matches "org\.springframework\.ws\.client\.core\.(WebServiceMessage|Source)Extractor" */
        type.name matches ".*\$\d$"
    ]

FunctionCall fc: function is [Function f:
/* (1) Function call of a getter that's not static */
    not static and
/* (2) Method is called get.* or is.*  */
    f.name matches "(get|is).*" and
/* (3) is a method of an entity class,  */
    f.enclosingClass is [Class:
            annotations contains [Annotation:
                    (type == T"javax.persistence.Entity" or
                    type == T"org.hibernate.annotations.Entity")]
    ] and
    /* (4) Function call of a getter that is @GeneratedValue (auto generated by the ORM framework)  */
    (
        f.annotations contains [Annotation: type.name == "javax.persistence.GeneratedValue"] or
        f contains [ReturnStatement rs: rs.expression.location is [FieldAccess fa: fa.field.annotations contains [Annotation a: a.type.name == "javax.persistence.GeneratedValue"]]]
    )
]

