ScriptedCallGraphRule.CallGraphScript:
function dbg(msg) {
      //echo(msg);
}

function findResolutions(originalResolution, context, args) {
        dbg("Entering findResolutions")
        var stringType = nameTable.getClassByName("java.lang", "String", "java");
        var name = args[0];
        var params = args[1];
        var types = args[2];
        var found = [];
        var OA_COsToAMs = loadPersistedObject("program.OA_COsToAMs");
        var srcClass = String(context.getEnclosingClass());
        dbg("Source class: "+srcClass);
        var tgtClasses = OA_COsToAMs[srcClass];
        dbg("Target classes: "+tgtClasses);
        for each (var tgtClassName in tgtClasses) {
                dbg("Target class name: "+tgtClassName);
                var tgtClass = nameTable.getClassByFullName(tgtClassName, "java");
                dbg("Target class: "+tgtClass);
                var callParams = types != null ? types.length : params != null ? params.length : 0;
                var callParamsSrc = types != null ? "types" : params != null ? "params" : "default";
                dbg("Src: "+callParamsSrc);
                methods:
                if (null != tgtClass && tgtClass.getName() != "[UnknownType]"){
                        for each (var fun in tgtClass.getMethods()) {
                                if (!fun.getName().equals(name)) {
                                        continue;
                                }
                                dbg("Method "+fun);
                                var argTypes = fun.getArgumentTypes();
                                if (argTypes !== undefined && argTypes !== null && callParams+1 != argTypes.length) {
                                        dbg("Call has "+callParams+", FunMeta has "+argTypes.length);
                                        continue;
                                }
                                if (types != null || params != null) {
                                        for (var i = 0; i < callParams; i++) {
                                                var tgtType = argTypes[i+1];
                                                if (types != null) {
                                                        if (!tgtType.equals(types[i])) {
                                                                dbg("Arg "+i+" mismatch: "+tgtType+" != "+types[i]);
                                                                continue methods;
                                                        }
                                                } else {
                                                        if (!tgtType.equals(stringType)) {
                                                                dbg("Arg "+i+" mismatch: "+tgtType+" != java.lang.String");
                                                                continue methods;
                                                        }
                                                }
                                        }
                                }
                                dbg("Found "+fun);
                                found[found.length] = fun;
                        }
                }
        }
        dbg("Found "+found.length+" matches");
        if (found.length > 0) {
                return found;
        } else {
                return null;
        }
}

function dbg(msg) {
     //echo(msg);
}
function findResolutions(originalResolution, context, args) {
    var found = [];
    dbg("Entering findResolutions");
    dbg("Context: " + context);
    dbg("Class " + originalResolution.getEnclosingClass().getName());
    dbg("Package " + originalResolution.getEnclosingClass().getPackageName());
    var methodName = originalResolution.getName();
    dbg("Method " + methodName);
    var proxyClass = originalResolution.getEnclosingClass();
    var proxiedClassName = String(nameTable.getLabelValue("GWTProxyFor", proxyClass));
    dbg("Proxied Class Name " + proxiedClassName);
    var proxiedClass = nameTable.getClassByFullName(proxiedClassName, "java");
    dbg("Proxied Class " + proxiedClass.getName());
    dbg("Proxied Package " + proxiedClass.getPackageName());
    if (proxiedClass != null && proxiedClass.getName() != "[UnknownType]") {
        for each (var fun in proxiedClass.getMethods()) {
            if (fun.getName().equals(methodName)) {
                dbg("Method found " + fun);
                found[found.length] = fun;
                break;
            }
        }
    }
    dbg("Found "+found.length+" matches");
    if (found.length > 0) {
        return found;
    } else {
        return null;
    }
}

ReturnTypeRule.Notes:
We want to add ModelMap as a reaching type for `map` in cases such as:

    public String handler(Model model, HttpServletRequest request) {
        Map modelMap = model.asMap();
        modelMap.put("user",request.getParameter("foo"));
        ...
    }

