Function f:
    /* Web method so bound to GET,POST,PUT,OPTIONS,HEAD or DELETE requests */
    annotations contains [Annotation b: b.type.name matches "javax\.ws\.rs\.(GET|POST|PUT|DELETE|OPTIONS|HEAD)"]
    /* Web Method does produce text/html response */
    and (
        (
            annotations contains [Annotation: 
                type == T"javax.ws.rs.Produces"
                and elements contains [AnnotationElement: 
                    key == "value" 
                    and (
                        value matches "(?i)text/html.*"
                        or value matches "(?i)application/xml.*"
                        or value is [ConstantArray: values contains [String: matches "(?i)text/html.*"]]
                        or value is [ConstantArray: values contains [String: matches "(?i)application/xml.*"]]
                    )
                ] 
            ] 
        ) or (
            not annotations contains [Annotation: type == T"javax.ws.rs.Produces"]
            and enclosingClass.annotations contains [Annotation: 
                type == T"javax.ws.rs.Produces"
                and elements contains [AnnotationElement: 
                    key == "value" 
                    and (
                        value matches "(?i)text/html.*"
                        or value matches "(?i)application/xml.*"
                        or value is [ConstantArray: values contains [String: matches "(?i)text/html.*"]]
                        or value is [ConstantArray: values contains [String: matches "(?i)application/xml.*"]]
                    )
                ]
            ]
        ) or (
            not annotations contains [Annotation: type == T"javax.ws.rs.Produces"]
            and not enclosingClass.annotations contains [Annotation: type == T"javax.ws.rs.Produces"]
        )
    )

