    }
}
if (issues2remove.length > 0) {
    var vulns = getVulnerabilities();
    for each (var vuln in vulns) {
        if (vuln !== null && (vuln.getPrimaryFile() === null || vuln.getPrimaryLine() === null)) continue;
        var ruleID = String(vuln.getRule().getIdentifier());
        if (ruleID.equals("8C44759E-8F16-494B-AC39-46D57E9F9863")) {
            var lineNumber = vuln.getPrimaryLine();
            var fileName = vuln.getPrimaryFile();
            for each (var p in issues2remove) {
                if (lineNumber == p['lineNumber'] && fileName == p['fileName']) {
                    vuln.remove();
                }
            }
        }
    }
}

/**
*  issues found when equality checks with toUpperCase()/toLowerCase() without using a locale may be got around due to locale.
*  if the defaultLocale is ever set, we assume that this is correct and delete all the issues
*/
function cleanupLocaleIssues(vuln, ruleid, possiblyDeleteList, defaultLocale){
    /* if defaultLocale already found, just delete anything already in list, and delete any vulns matching one of the rule IDs */
    if (defaultLocale === true){
        for each (var vuln in possiblyDeleteList){
            vuln.remove();
        }
        if (ruleid == "D8E9ED3B-22EC-4CBA-98C8-7C67F73CCF4C" || ruleid == "6C9922D7-1DFD-4EE4-AA01-7D7613938577"){
            vuln.remove();
        }
    }else{
        /* if defaultLocale not already found, try to see if it can be, and add to possibleDeleteList */
        if (ruleid == "D8E9ED3B-22EC-4CBA-98C8-7C67F73CCF4C"){
            dbg("adding to list IID: " + vuln.getInstanceIdentifier());
            possiblyDeleteList.push(vuln);
        }else if (ruleid == "6C9922D7-1DFD-4EE4-AA01-7D7613938577"){
            dbg("Found locale default set programmatically");
            defaultLocale = true;
            vuln.remove();
        }
    }
    return defaultLocale;
}

function cleanup(){
    var vulns = getVulnerabilities();
    var localeDependentIssues = new Array();
    var defaultLocale = false;

    for each (var vuln in vulns){
        var ruleid = vuln.getRule().getIdentifier();
        if (ruleid !== undefined && ruleid !== null){
            defaultLocale = cleanupLocaleIssues(vuln, ruleid, localeDependentIssues, defaultLocale);
        }
    }
}

function dbg(msg){
    //alert(msg);
}

cleanup();

ScriptDefinitions.Script:
var MASS_ASSIGNMENT_REGEXP = /admin|role|access|price|cost|secret|priv/i;

function processField(field, visited) {
    // Loop through nested fields in the given class if they are not primitive or System classes
    // If field name matches Mass Assignment regular expression, label it with exposedRESTField
    var name = String(field.getName());
    var type = field.getType();
    var key = String(type.getPackageName() + "." + type.getName());
    if (name.match(MASS_ASSIGNMENT_REGEXP)) {
        field.setLabel("exposedRESTField");
    }
    if (!type.isPrimitive() && !key.match(/^(java|null).*/) && visited[key] != true) {
        visited[key] = true;
        var fields = type.getFields();
        if (fields != null) {
            for each (var new_field in fields) {
                var new_key = new_field.getType().getPackageName() + "." + new_field.getType().getName();
                if (visited[new_key] != true) {
                    processField(new_field, visited);
                }
            }
        }
    }
}
// Collect all command classes
var cmclasses = nameTable.getClassesByLabel("RESTInsecureBinding", "java");
if (cmclasses !== null) {
    for each (var cmclass in cmclasses) {
        if (cmclass !== null && cmclass != "[UnknownType]") {
            var visited = {};
            visited[cmclass.getPackageName() + "." + cmclass.getName()] = true;
            /*
                If JAXB binds a class to XML, then, by default, all public members will be bound, i.e., public getter and setter pairs, or public fields. Any protected, package-visible or private member is bound if it is annotated with a suitable annotation such as XmlElement or XmlAttribute. You have several possibilities to influence this default behaviour.

                You can annotate a package or a top level class with XmlAccessorType, setting its value element to one of the enum constants FIELD, PROPERTY, PUBLIC_MEMBER or NONE. If FIELD is set every non static, non transient field will be automatically bound. PROPERTY instructs JAXB to do this for getter and setter pairs. NONE suppresses bind except for explicitly annotated fields or properties. A class without this annotation inherits the XmlAccessorType setting either from its superclass or from the package setting.

                The other annotation to be mentioned in this context is XmlTransient. It suppresses binding for its target which can be an entire class or a field or a method. This is also useful if you have a name clash resulting from a public field, say foo, and methods getFoo and setFoo.
            */
            var jaxbann = cmclass.getAnnotation("javax.xml.bind.annotation.XmlRootElement");
            var fields = cmclass.getFields();
            var methods = cmclass.getMethods();
            if (jaxbann !== undefined && jaxbann !== null) {
                var acctype = cmclass.getAnnotation("javax.xml.bind.annotation.XmlAccessorType");
                if (acctype !== undefined && acctype !== null) {
                    if (acctype.get("value").getEnumValue() == "NONE") {
                        // NONE accessor type: only XmlElement or XmlAttribute annotated fields
                        for each (var field in fields) {
                            var XmlElement = field.getAnnotation("javax.xml.bind.annotation.XmlElement");
                            var XmlAttribute = field.getAnnotation("javax.xml.bind.annotation.XmlAttribute");
                            var XmlTransient = field.getAnnotation("javax.xml.bind.annotation.XmlTransient");
                            if (((XmlElement !== null && XmlElement !== undefined) || (XmlAttribute !== null && XmlAttribute !== undefined)) && (XmlTransient === null || XmlTransient === undefined)) {
                                processField(field, visited);
                            }
                        }
                    } else if (acctype.get("value").getEnumValue() == "PROPERTY") {
                        // PROPERTY accessor type: only fields with public getters, and setters
                        for each (var field in fields) {
                            var getter = "get" + field.getName().toLowerCase();
                            var setter = "set" + field.getName().toLowerCase();
                            has_setter = has_getter = false;
                            for each (var method in methods) {
                                if (getter == method.getName().toLowerCase() && method.getSymbol().isPublic()) {
                                    var XmlTransient = method.getAnnotation("javax.xml.bind.annotation.XmlTransient");
                                    if (XmlTransient === null || XmlTransient === undefined) has_getter = true;
                                }
                                if (setter == method.getName().toLowerCase() && method.getSymbol().isPublic()) {
                                    var XmlTransient = method.getAnnotation("javax.xml.bind.annotation.XmlTransient");
                                    if (XmlTransient === null || XmlTransient === undefined) has_setter = true;
                                }
                            }
                            if (has_setter && has_getter) {
                                var XmlTransient = field.getAnnotation("javax.xml.bind.annotation.XmlTransient");
                                if (XmlTransient === null || XmlTransient === undefined) {
                                    processField(field, visited);
                                }
                            }
                        }
                    } else if (acctype.get("value").getEnumValue() == "FIELD")  {
                        // FIELD accessor type: non static, non transient fields
                        for each (var field in fields) {
                            var XmlTransient = field.getAnnotation("javax.xml.bind.annotation.XmlTransient");
                            // Bug 43992: FieldMeta does not has any isTransient method :(
                            // Bug 43991 jsField.getSymbol is protected (it is public in jsMethod) So we cannot check if field is static
                            // if (!field.getSymbol().iStatic() && (XmlTransient === null || XmlTransient === undefined)) {
                            if (XmlTransient === null || XmlTransient === undefined) {
                                processField(field, visited);
                            }
                        }
                    }
                } else {
                    // No Accessor type so: only public fields or private/protected ones with XmlTransient, XmlElement or XmlAttribute
                    for each (var field in fields) {
                        var XmlElement = field.getAnnotation("javax.xml.bind.annotation.XmlElement");
                        var XmlAttribute = field.getAnnotation("javax.xml.bind.annotation.XmlAttribute");
                        var XmlTransient = field.getAnnotation("javax.xml.bind.annotation.XmlTransient");
                        // Bug 43991 jsField.getSymbol is protected (it is public in jsMethod) So we cannot check if field is static
                        // if ((field.getSymbol().isPublic() || (XmlElement !== null && XmlElement !== undefined) || (XmlAttribute !== null && XmlAttribute !== undefined)) && (XmlTransient === null || XmlTransient === undefined)){
                        if (((XmlElement !== null && XmlElement !== undefined) || (XmlAttribute !== null && XmlAttribute !== undefined)) && (XmlTransient === null || XmlTransient === undefined)){
                            processField(field, visited);
                        }
                    }
                }
            }
        }
    }
}

ScriptDefinitions.ScriptDefinition:
dbg("here");
if(typeof nameTable.getClassByName != 'undefined') {
  dbg("and now here");
  for each (var bean in program.form_beans) {
if (null != bean) {
  bean.vf = false;                 // whether the bean is a ValidatorForm
  bean.vaf = false;                // whether the bean is a ValidatorActionForm
  bean.dvf = false;                // whether the bean is a DynaValidatorForm
  bean.dvaf = false;               // whether the bean is a DynaValidatorActionForm

  var dotIndex = bean.clss.lastIndexOf(".");
  var beanClass = nameTable.getClassByName(bean.clss.substring(0, dotIndex), bean.clss.substr(dotIndex+1), "java");
  dbg("bean.clss: " + bean.clss);
  addFields(beanClass, bean.clss, bean);
  traverseSuperClasses(beanClass, bean.clss, bean);
}
  }
}

function traverseSuperClasses(clss, clssName, bean) {
  // I don't think we want to check for '[UnknownType]' == clss.getName() because this will break recursion
  if (null == clss) {
return;
  }

  dbg("clssName: " + clssName);
  if (clssName == "org.apache.struts.validator.ValidatorForm" ||
  clssName == "org.apache.struts.validator.ValidatorActionForm" ||
  clssName == "org.apache.struts.validator.DynaValidatorForm" ||
  clssName == "org.apache.struts.validator.DynaValidatorActionForm") {
determineFormKind(bean.clss, bean);
return;
  }
  else if (clssName != "org.apache.struts.action.ActionForm" && clssName != "org.apache.struts.action.DynaActionForm") {
var superClasses = clss.getSuperClasses();

if (null == superClasses || 0 == superClasses.length) {
  return;
}

for each (var superC in superClasses) {
  if (null == superC.getPackageName() || 0 == superC.getPackageName().length) {
    fullName = superC.getName();
  }
  else {
    fullName = superC.getPackageName() + "." + superC.getName();
  }
  dbg("fullName: " + fullName);
  determineFormKind(fullName, bean);
  addFields(superC, fullName, bean);
  traverseSuperClasses(superC, fullName, bean);
}
  }
}

function determineFormKind(className, bean) {
  if (className == "org.apache.struts.validator.ValidatorForm") {
bean.vf = true;
dbg("bean.vf: " + bean.vf);
  }
  else if (className == "org.apache.struts.validator.ValidatorActionForm") {
bean.vf = true;
bean.vaf = true;
dbg("bean.vaf: " + bean.vaf);
  }
  else if (className == "org.apache.struts.validator.DynaValidatorForm") {
bean.dvf = true;
dbg("bean.dvf: " + bean.dvf);
  }
  else if (className == "org.apache.struts.validator.DynaValidatorActionForm") {
bean.dvf = true;
bean.dvaf = true;
dbg("bean.dvaf: " + bean.dvaf);
  }
}

function addFields(clss, className, bean) {
  var field = "";
  var methods = null;
  if (null != clss && '[UnknownType]' != clss.getName()) {
methods = clss.getMethods();
if (null != methods) {
  for each (var m in methods) {
    dbg("method name: " + m.getName());
    if (null != m && null != m.getName().match(/^set.*/)) {
      field = m.getName().substr(3, 1).toLowerCase() + m.getName().substr(4);
      dbg("addField method: " + m.getName());
      dbg("addField field: " + field);
      var thisField = new Object();
      thisField.fieldName = field;
      thisField.className = className;
      bean.fields[bean.fields.length] = thisField;
      dbg("adding to bean.fields: " + thisField.className + "." + thisField.fieldName);
    }
  }
}
  }
}

var thisResult = null;
program.struts1_validated_fields = new Array();
dbg("in struts1_validated_fields script");

for each (var a in program.struts1_actions) {
  dbg("in first for each");
  if (0 != a.name.length) {
    dbg("in first if: a.name");
    var bean = program.form_beans[a.name];
    dbg("bean: " + bean);
    if (null != bean) {
      dbg("in second if");
      for each (var v in program.validation_forms) {
        dbg("in second for each");
        if (null != v) {
          dbg("in thids if");
          // for ValidatorForm and DynaValidatorForm, look up by name, for ValidatorActionForm and DynaValidatorActionForm, look up by path
          // for non Validator forms, report based on the path
          if (((true == bean.vaf || true == bean.dvaf) && a.path == v.name) ||
           (((true == bean.vf && false == bean.vaf) || (true == bean.dvf && false == bean.dvaf)) && a.name == v.name)) {
            dbg("in fourth if");
            if (null != bean.fields && 0 != bean.fields.length) {
              dbg("in fifth if");
              for each (var m in bean.fields) {
                found = false;
                dbg("field name: " + m.fieldName);
                if (null != m) {
                  dbg("in sixth if");
                  for (var f in v.fields) {
                    dbg("in third for each");
                    if (m.fieldName == f) {
                      found = true;
                      dbg("found = true");
                      break;
                    }
                  }
                  if (true == found) {
                    var resultArrayElement = new Object();
                    resultArrayElement.fileNames = new Array();
                    resultArrayElement.fileNames[0] = bean.fileName;
                    resultArrayElement.fileNames[1] = a.fileName;
                    resultArrayElement.fileNames[2] = v.fileName;
                    resultArrayElement.lineNumbers = new Array();
                    resultArrayElement.lineNumbers[0] = bean.lineNumber;
                    resultArrayElement.lineNumbers[1] = a.lineNumber;
                    resultArrayElement.lineNumbers[2] = v.fields[f];
                    resultArrayElement.source = "get" + m.fieldName.substr(0, 1).toUpperCase() + m.fieldName.substr(1);

                    if (null == program.struts1_validated_fields[m.className]) {
                      thisResult = new Array();
                    }
                    else {
                      thisResult = program.struts1_validated_fields[m.className];
                    }
                    thisResult[thisResult.length] = resultArrayElement;
                    program.struts1_validated_fields[m.className] = thisResult;
                    dbg("validated field's getter: " + resultArrayElement.getter);
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

        //
        // Set up data structures for struts beans and actions
        //
        function init_struts2() {
          var ns = new Namespace("");
          var beanCount = 0;
          var actionCount = 0;
          program.struts_beans = new Array();
          program.struts_actions = new Array();
          for (var cfgName in program.xml) {
            var cfg = program.xml[cfgName];
            if (null != cfg) {
              if (cfg.name() != "struts") {
                continue;
              }
              for each (var j in cfg..ns::bean) {
                var thisBean = new Object();
                thisBean.name = String(j["@name"]);
                thisBean.clss =  String(j["@class"]);

                // make sure we're dealing with valid Java class
                if (false == isValidJavaPackageName(thisBean.clss)) {
                  continue;
                }

                var scope = String(j["@scope"]);
                var singleton_attr= String(j["@singleton"]);
                if (singleton_attr.toLowerCase() == "true" || (singleton_attr === null && (scope == "" || scope == null || scope == "singleton" || scope == "Singleton"))) {
                    thisBean.singleton = true;
                }
                program.struts_beans[beanCount++] = thisBean;
              }
              for each (var k in cfg..ns::action){
                var thisAction = new Object();
                thisAction.name = String(k["@name"]);
                thisAction.clss = String(k["@class"]);
                thisAction.fileName = cfgName;
                thisAction.lineNumber = k.getLineNumber();

                var views = [];
                for each (var r in k..ns::result){
                    views[views.length] = String(r);
                }
                thisAction.views = views;

                var params= {};
                for each (var p in k..ns::param){
                    params[String(p["@name"])] = String(p);
                }
                thisAction.params= params;

                var dotIndex = thisAction.clss.lastIndexOf(".");
                thisAction.namespaceName = thisAction.clss.substring(0, dotIndex);
                thisAction.className = thisAction.clss.substr(dotIndex+1);

                // make sure we're dealing with valid Java class name
                if (null != thisAction.clss && 0 != thisAction.clss.length && isValidJavaPackageName(thisAction.clss)) {
                  program.struts_actions[actionCount++] = thisAction;
//alert("action namespace: " + thisAction.namespaceName);
//alert("action class: " + thisAction.className);
                }
              }
            }
          }
        }

        if (null == program.struts_beans || null == program.struts_actions) {
//alert("java: INITIALIZING STRUTS 2");
          init_struts2();
        }
        else {
//alert("java: STRUTS 2 HAS ALREADY BEEN INITIALIZED");
        }
        if (null != program && null != program.struts_actions) {
        persistObject("program.struts_actions2", program.struts_actions);
        }

var strutsActions = loadPersistedObject("program.struts_actions2");
if (strutsActions !== null) {
    for each (var action in strutsActions) {
        if (action !== null && action !== undefined && action.clss !== null && action.clss !== undefined && action.clss == "org.apache.struts2.s1.Struts1Action") {
            //alert("Struts1 Plugin action detected");
            var cn = action.params['className'];
            if (cn !== "null" && cn !== null && cn !== undefined) {
                var actionClass = nameTable.getClassByFullName(cn, "java");
                //alert(actionClass.getName());
                if (actionClass != null && actionClass != undefined && '[UnknownType]' != actionClass.getName()) {
                    //alert("Labeling " + cn);
                    actionClass.setLabel("Struts1PluginAction");
                }
            }
        }
    }
}

program.struts2_validated_fields = new Array();
default xml namespace = new Namespace("");
var fieldns = new Namespace("");

// add in validated action field names
for each (var act in program.struts_actions) {
  for (var fileName in program.xml) {
    var shortFileName = "";
    if (-1 != fileName.lastIndexOf("/")) {
      shortFileName = fileName.substring(fileName.lastIndexOf("/")+1);
    }
    else {
      shortFileName = fileName.substring(fileName.lastIndexOf("\\")+1);
    }
    dbg("shortFileName: " + shortFileName)
    if (shortFileName.match("^" + act.className) && shortFileName.match("validation.xml$")) {
      //act.validated_fields = new Array();
      dbg("FILES MATCHED: " + fileName);
      var validationFile = new XML(program.xml[fileName]);
      dbg("STUFF: " + validationFile..fieldns::field);
      for each (var j in validationFile..fieldns::field) {
        dbg("ADDING: " + String(j["@name"]));
        var lineNumber = j.getLineNumber();
        iterateOverNestedProperties(act.clss, String(j["@name"]), fileName, lineNumber, act.fileName, act.lineNumber);
      }
      dbg("foo: " + validationFile..fieldns::validator.fieldns::param.(@name == "fieldName"));
      for each (var j in validationFile..fieldns::validator.fieldns::param.(@name == "fieldName")) {
        dbg("ADDING: " + String(j));
        var lineNumber = j.getLineNumber();
        iterateOverNestedProperties(act.clss, String(j["@name"]), fileName, lineNumber, act.fileName, act.lineNumber)
      }
    }
  }
}
default xml namespace = new Namespace("xmlns://www.fortifysoftware.com/schema/rules");

function addValidatedField(className, fieldName, fileName, lineNumber, actionFileName, actionLineNumber) {
  var thisResult = null;
  var resultArrayElement = new Object();
  resultArrayElement.fileNames = new Array();
  resultArrayElement.fileNames[0] = actionFileName;
  resultArrayElement.fileNames[1] = fileName;
  resultArrayElement.lineNumbers = new Array();
  resultArrayElement.lineNumbers[0] = actionLineNumber;
  resultArrayElement.lineNumbers[1] = lineNumber;
  resultArrayElement.source = "set" + fieldName.substr(0, 1).toUpperCase() + fieldName.substr(1);

  if (null == program.struts2_validated_fields[className]) {
    thisResult = new Array();
  }
  else {
    thisResult = program.struts2_validated_fields[className];
  }
  thisResult[thisResult.length] = resultArrayElement;
  program.struts2_validated_fields[className] = thisResult;
  dbg("validated field's setter: " + resultArrayElement.source);
}

function iterateOverNestedProperties(actionClass, inputValue, fileName, lineNumber, actionFileName, actionLineNumber) {
  var props = inputValue.split(".");

  var cName = actionClass;
  if (null != props) {
    for (var index = 0; index < props.length-1; index++) {
      if (isValidJavaIdentifier(props[index])) {
        var getter =  "get" + props[index].substr(0, 1).toUpperCase() + props[index].substr(1);
        cName = queryMetaTableForFunctionReturnType(cName, getter);
      }
    }
  }

  dbg("ADDING: cName: " + cName + ", fieldName: " + props[props.length-1]);
  addValidatedField(cName, props[props.length-1], fileName, lineNumber, actionFileName, actionLineNumber);
}

function getAndroidMinSdkVersion() {
    var xmlFiles = getXMLConfigFileNames();
    var ns = new Namespace();
    for each (var filename in xmlFiles) {
        var lowername = String(filename).toLowerCase();
        var suffix = "androidmanifest.xml";
        if (lowername.indexOf(suffix, lowername.length - suffix.length) < 0) continue;
        try {
            var contents = readFile(filename);
            if (contents.charAt(0) != '<') {
                contents = contents.substring(1);
            }
            var xml = new XML(contents);
            if (null !== xml && null !== xml.name() && null !== xml.name().localName && xml.name().localName.toLowerCase() == "manifest") {
                if (xml.children() !== null) {
                    for each (var j in xml.children()) {
                        if (null !== j && null !== j.name() && null !== j.name().localName && j.name().localName.toLowerCase() == "uses-sdk") {
                            if (j.attributes() !== null) {
                                for each (var attr in j.attributes()) {
                                    if (attr !== null && attr.localName() !== null) {
                                        if ("minsdkversion" == attr.localName().toLowerCase()) return parseInt(String(attr));
                                    }
                                }
                            }
                        }
                    }
                }
            }
        } catch (err) {
            // actively ignoring XML parsing errors. Not much help to customers. See bug 31939 for more details.  
            // log("Error processing file: " + filename + " as an XML file. Exception thrown was: " + err + ". Please review the file for any syntax errors.");
        }
    }
}

var jsclasses = nameTable.getClassesByLabel("AndroidJavascriptAccessible", "java");
if (jsclasses !== null && jsclasses !== undefined) {
    for each (var jsclass in jsclasses) {
        if (jsclass !== null && jsclass !== undefined) {
            var before_Jelly_Bean = true;
            var version = getAndroidMinSdkVersion();
            if (!isNaN(version) && version > 16) before_Jelly_Bean = false;
            var methods = jsclass.getMethods();
            var annotatedMethods = [];
            var allMethods = [];
            if (methods !== null && methods !== undefined) {
                for each (var method in methods) {
                    allMethods[allMethods.length] = method;
                    var annotation = method.getAnnotation("android.webkit.JavascriptInterface");
                    if (annotation !== null && annotation !== undefined) {
                        // Commenting out since even if there are annotations, the app can run in insecure mode if
                        // minSdkVersion < 17 and app is installed in an Android device with version 4.1 or lower.
                        //before_Jelly_Bean = false;
                        annotatedMethods[annotatedMethods.length] = method;
                    }
                }
                if (before_Jelly_Bean) {
                    // All methods are entrypoints (the entrypoint rule will make sure they are public and not constructors)
                    for each (var m in allMethods) {
                        m.setLabel("AndroidJavascriptAccessibleMethod");
                    }
                    // JS exposed class is vulnerable to Mitm attacks leading to RCE
                    jsclass.setLabel("AndroidJavascriptVulnerable");
                } else {
                    // only annotated methods are entrypoints (the entrypoint rule will make sure they are public and not constructors)
                    for each (var m in annotatedMethods) {
                        m.setLabel("AndroidJavascriptAccessibleMethod");
                    }
                }
            }
        }
    }
}

     // Because of the bug in <= 3.7 scripting API, these two functions are put into a separate <Script/> element
     // The bug consisted in doing namespaceName + className (instead of namespaceName + "." + className) when actually looking up the types in the nameTable
     // The workaround for the bug is to pass "" for namespaceName and a full  name for the class
     // 3.7 version of this script does exactly this, while 3.9 version of the script assumes that the bug is fixed

    //
    // This funtion adds a label to a particular field of a class
    function addLabelToField(namespaceName, className, fieldName, labelToUse) {
//dbg("i am in addLabelToField: " + namespaceName + " : " + className + " : " + fieldName + " : " + labelToUse);
      if(typeof nameTable.getClassByName != 'undefined') {
//dbg("6666666666666666666666666666666");
        var beanClass = nameTable.getClassByName(namespaceName, className, "java");
        if (null != beanClass && '[UnknownType]' != beanClass.getName()) {
//dbg("class not null");
          var beanClassFields = beanClass.getFields();
          if (null != beanClassFields) {
//dbg("fields not null");
        for (var i = 0; i < beanClassFields.length; i++) {
//dbg("inside for loop");
          if (null != beanClassFields[i]) {
//dbg("field not null: " + beanClassFields[i].getName());
            if (beanClassFields[i].getName() == String(fieldName)) {
//dbg("in if after");
              beanClassFields[i].setLabel(labelToUse);
//dbg("i set label " + labelToUse + " to field " + fieldName + " of class " + className);
              break;
            }
          }
        }
          }
        }
      }
    }

    //
    // This funtion adds a label to all fields of a class
    function addLabelToFields(namespaceName, className, labelToUse) {
//dbg("adding label '" + labelToUse + "' to fields in namespace '" + namespaceName + "' and class '" + className + "'");
//alert("adding label '" + labelToUse + "' to fields in namespace '" + namespaceName + "' and class '" + className + "'");
      if(typeof nameTable.getClassByName != 'undefined') {
//dbg("in first if");
        var actionClass = nameTable.getClassByName(namespaceName, className, "java");
        if (null != actionClass && '[UnknownType]' != actionClass.getName()) {
//dbg("in second if: " + actionClass.getName());
          var actionClassFields = actionClass.getFields();
          if (null != actionClassFields) {
//dbg("in third if: " + actionClassFields.length);
        for (var i = 0; i < actionClassFields.length; i++) {
//dbg("here");
          if (null != actionClassFields[i]) {
//dbg("adding label '" + labelToUse + "' to field '" + actionClassFields[i].getName() + "' in '" + namespaceName + "." + className + "'");
//alert("adding label '" + labelToUse + "' to field '" + actionClassFields[i].getName() + "' in '" + namespaceName + "." + className + "'");
            actionClassFields[i].setLabel(labelToUse);
          }
        }
          }
        }
      }
    }

 function extractLabelValues(obj, prefix) {
    var values = [];
    if (obj !== null && prefix !== null && prefix !== "") {
        var labels = obj.getLabels();
        if (labels !== null) {
            for each (var l in labels) {
                if (l.indexOf(prefix) == 0) {
                    var value = String(l.substring(prefix.length));
                    if (value != null && value.length > 0) {
                        values[values.length++] = value;
                    }
                }
            }
        }
    }
    return values;
}

function isAction(cls) {
    return endsWith(cls, "Action") ||
            cls == "org.springframework.webflow.action.FormAction" ||
            isSubClass(cls, "org.springframework.webflow.action.FormAction");
}

function isCommand(cls) {
    return endsWith(cls, "Controller") ||
            isSubClass(cls, "org.springframework.web.servlet.mvc.BaseCommandController");
}

function isExporter(cls) {
    return cls == "org.springframework.remoting.caucho.HessianServiceExporter" ||
            cls == "org.springframework.remoting.caucho.BurlapServiceExporter" ||
            cls == "org.springframework.remoting.httpinvoker.HttpInvokerServiceExporter" ||
            cls == "org.springframework.remoting.rmi.RmiServiceExporter" ||
            isSubClass(cls, "org.springframework.remoting.rmi.RmiServiceExporter") ||
            cls == "org.codehaus.xfire.spring.remoting.XFireExporter" ||
            isSubClass(cls, "org.codehaus.xfire.spring.remoting.XFireExporter") ||
            cls == "org.springframework.remoting.httpinvoker.HttpInvokerProxyFactoryBean" ||
            isSubClass(cls, "org.springframework.remoting.support.RemoteAccessor") ||
            isSubClass(cls, "org.springframework.remoting.support.RemoteExporter");
}

function markSensitiveField(field, visited) {
    var MASS_ASSIGNMENT_REGEXP = /admin|role|access|price|cost|secret|priv/i;
    var name = String(field.getName());
    var type = field.getType();
    var key = String(type.getPackageName() + "." + type.getName());
    if (name.match(MASS_ASSIGNMENT_REGEXP)) {
        field.setLabel("exposedWebflowFormField");
    }
    if (!type.isPrimitive() && !key.match(/^(java|null).*/) && visited[key] != true) {
        visited[key] = true;
        var fields = type.getFields();
        if (fields != null) {
            for each (var new_field in fields) {
                var new_key = new_field.getType().getPackageName() + "." + new_field.getType().getName();
                if (visited[new_key] != true) {
                    markSensitiveField(new_field, visited);
                }
            }
        }
    }
}

function initSpringLabeling() {

    var spring_beans = loadPersistedObject("program.spring_beans");

    // Complete spring bean references with convention and scanned components
    var spring_refs = loadPersistedObject("program.spring_refs");
    if (spring_refs !== null) {
        var classes = nameTable.getClassesByLabel("SpringBean", "java");
        if (classes !== null) {
            for each (var c in classes) {
                var name = String(c.getPackageName()) + "." + String(c.getName());
                var refs = extractLabelValues(c, "SpringBeanRef::");
                if (refs !== null && refs !== undefined && refs.length > 0) {
                    for each(var alias in refs) {
                        if (alias !== null && alias !== undefined && alias !== "") spring_refs[alias] = name;
                    }
                } else {
                    var ref = String(c.getName());
                    ref = ref.substr(0, 1).toLowerCase() + ref.substr(1);
                    if (spring_refs[ref] === null || spring_refs[ref] === undefined) {
                        spring_refs[ref] = name;
                    }
                }
            }
        }
    }

    // Add Spring beans refs to spring_beans
    for (var name in spring_refs) {
        var found = false;
        for each (var bean in spring_beans) {
            if (bean.name == name) {
                found = true;
                break;
            }
        }
        if (!found) {
            var thisBean = new Object();
            thisBean.name = name;
            thisBean.clss = spring_refs[name];
            spring_beans[spring_beans.length++] = thisBean;
        }
    }
    persistObject("program.spring_beans", spring_beans);

    // Process JMS listeners in jms namespace
    var spring_jms_listeners = loadPersistedObject("program.spring_jms_listeners");
    if (spring_jms_listeners !== null) {
        for (var ref in spring_jms_listeners) {
            if (ref !== null && ref !== undefined && ref != "") {
                var refclass = spring_refs[ref];
                var exposedmethods = spring_jms_listeners[ref];
                var listenerClass = nameTable.getClassByFullName(refclass, "java");
                if (listenerClass !== null && listenerClass !== undefined && listenerClass.getName() != "[UnknownType]") {
                    var methods = listenerClass.getMethods();
                    if (methods !== null) {
                        for each (var method in methods) {
                            if (method !== null && method !== undefined && method.getName() != "[UnknownType]") {
                                for each (var exposedmethod in exposedmethods) {
                                    if (method.getName() == exposedmethod) {
                                        method.setLabel("SpringJmsListenerMethod");
                                        break;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    // Process JMS Listener Adapters (JavaConfig)
    var methods = nameTable.getMethodsByLabel("SpringJmsListenerAdapter", "java");
    if (methods !== null && methods !== undefined) {
        for each (var m in methods) {
            var cname = extractLabelValues(m, "SpringJmsListenerAdapter::ClassName::");
            var mname = extractLabelValues(m, "SpringJmsListenerAdapter::MethodName::");
            if (cname !== null && cname !== undefined && cname.length > 0) {
                var listenerClass = nameTable.getClassByFullName(cname, "java");
                if (listenerClass !== null && listenerClass !== undefined && listenerClass.getName() != "[UnknownType]") {
                    var dispatcher = null;
                    if (mname !== null && mname !== undefined && mname.length > 0) dispatcher = mname[0];
                    else dispatcher = "handleMessage";
                    for each (var lmethod in listenerClass.getMethods()) {
                        if (lmethod.getName() == dispatcher) {
                            lmethod.setLabel("SpringJmsListenerMethod");
                            break;
                        }
                    }
                }
            }
        }
    }

    // Process JMS Listener Adapters (XML)
    for each (var bean in spring_beans) {
        if (bean.isJMSListenerAdapter) {
            // Get listener class
            var listenerClass = null;
            if (bean.listener !== undefined && bean.listener !== null && bean.listener.length >0) {
                listenerClass = nameTable.getClassByFullName(bean.listener, "java");
            } else if (bean.listenerRef !== undefined && bean.listenerRef !== null && bean.listenerRef.length >0) {
                for (var ref in spring_refs) {
                    if (ref == bean.listenerRef) {
                        var he = splitFullyQualifiedClsName(spring_refs[ref]);
                        listenerClass = nameTable.getClassByName(he.ns, he.clsName, "java");
                        break;
                    }
                }
            } else {
                for each (var propHolder in bean.propertyElements) {
                    if (propHolder.name == "delegate") {
                        for (var ref in spring_refs) {
                            if (ref == propHolder.value) {
                                var he = splitFullyQualifiedClsName(spring_refs[ref]);
                                listenerClass = nameTable.getClassByName(he.ns, he.clsName, "java");
                                break;
                            }
                        }
                    }
                }
            }

            // Get listener method
            var dispatcher = null;
            for each (var propHolder in bean.propertyElements) {
                if (propHolder.name == "defaultListenerMethod") {
                    dispatcher = propHolder.value;
                }
            }
            if (dispatcher === null || dispatcher == "") dispatcher = "handleMessage";

            // Label listener method
            if (listenerClass !== null && listenerClass !== undefined && listenerClass.getName() != "[UnknownType]") {
                for each (var lmethod in listenerClass.getMethods()) {
                    if (lmethod.getName() == dispatcher) {
                        lmethod.setLabel("SpringJmsListenerMethod");
                        break;
                    }
                }
            }
        }
    }

    for each (var bean in spring_beans) {

        // Label Singletons and Session scoped beans
        var dotIndex = String(bean.clss).lastIndexOf(".");
        var nsName = String(bean.clss).substring(0, dotIndex);
        var cName = String(bean.clss).substr(dotIndex+1);
        var beanClass = nameTable.getClassByName(nsName, cName, "java");
        if (beanClass !== null && '[UnknownType]' != beanClass.getName()) {
            if (bean.isSingleton && isSafeForJavaGlobal(beanClass)) {
                beanClass.setLabel("SpringSingletonBean");
            }
            if (bean.isSessionScoped && isSafeForJavaGlobal(beanClass)) {
                beanClass.setLabel("SpringSessionBean");
            }
            if (bean.isApplicationScoped && isSafeForJavaGlobal(beanClass)) {
                beanClass.setLabel("SpringApplicationBean");
            }
        }
        // Process Remoted beans, command classes and WebFlow Actions
        if ( bean.clss && (isAction(bean.clss) || isCommand(bean.clss) || isExporter(bean.clss)) ) {
            if (bean.propertyElements != null && Array(bean.propertyElements).length != 0) {
                for each (var propHolder in bean.propertyElements) {

                    if (propHolder.name == "formObjectClass" || propHolder.name == "commandClass") {
                        var dotIndex = String(propHolder.value).lastIndexOf(".");
                        var nsName = String(propHolder.value).substring(0, dotIndex);
                        var cName = String(propHolder.value).substr(dotIndex+1);
                        if (propHolder.name == "formObjectClass") {
                            var beanClass = nameTable.getClassByName(nsName, cName, "java");
                            if (beanClass != null && '[UnknownType]' != beanClass.getName()) {
                                beanClass.setLabel("webflowFormObject");
                                var visited = {};
                                visited[beanClass.getPackageName() + "." + beanClass.getName()] = true;
                                var fields = beanClass.getFields();
                                if (fields !== null && fields !== undefined) {
                                    // Loop through the command class fields and look for other non primitive nor java classes nested in the object
                                    for each (var field in fields) {
                                        markSensitiveField(field, visited);
                                    }
                                }
                            }
                            if (nsName != null && cName != null) {
                               addLabelToFields(nsName, cName, "Webflow1FormInput");
                            }
                        } else if (propHolder.name == "commandClass") {
                            var beanClass = nameTable.getClassByName(nsName, cName, "java");
                            if (beanClass != null && '[UnknownType]' != beanClass.getName()) {
                                beanClass.setLabel("spring2CommandObject");
                            }
                            if (nsName != null && cName != null) {
                                addLabelToFields(nsName, cName, "commandField");
                            }
                        }
                    } else if (propHolder.name == "service") {
                        for (var ref in spring_refs) {
                            if (ref == propHolder.ref) {
                                var he = splitFullyQualifiedClsName(spring_refs[ref]);
                                var beanClass = nameTable.getClassByName(he.ns, he.clsName, "java");
                                if (beanClass !== null && '[UnknownType]' != beanClass.getName()) {
                                    beanClass.setLabel("RemotedBean");
                                }
                                break;
                            }
                        }
                    } else if (propHolder.name == "serviceInterface") {
                        var he = splitFullyQualifiedClsName(propHolder.value);
                        var beanClass = nameTable.getClassByName(he.ns, he.clsName, "java");
                        if (beanClass !== null && beanClass !== undefined && '[UnknownType]' != beanClass.getName()) {
                            beanClass.setLabel("RemotedBean");
                        }
                    } else if (propHolder.name == "serviceBean") {
                        for (var ref in spring_refs) {
                            if (ref == propHolder.ref) {
                                var he = splitFullyQualifiedClsName(spring_refs[ref]);
                                var beanClass = nameTable.getClassByName(he.ns, he.clsName, "java");
                                if (beanClass !== null && '[UnknownType]' != beanClass.getName()) {
                                    beanClass.setLabel("WebServiceBean");
                                }
                                break;
                            }
                        }
                    }
                }
            }
        }

        // Check JMX beans
        if (bean.clss !== null && bean.clss !== undefined && bean.clss == "org.springframework.jmx.export.MBeanExporter") {
            if (bean.jmxEntryElements !== null && bean.jmxEntryElements !== undefined && Array(bean.jmxEntryElements).length > 0) {
                for each (var jmxEntryHolder in bean.jmxEntryElements) {
                    for (var ref in spring_refs) {
                        if (ref == jmxEntryHolder.value_ref) {
                            var he = splitFullyQualifiedClsName(spring_refs[ref]);
                            var beanClass = nameTable.getClassByName(he.ns, he.clsName, "java");
                            if (beanClass !== null && '[UnknownType]' != beanClass.getName()) {
                                beanClass.setLabel("JMXBean");
                            }
                            break;
                        }
                    }
                }
            }
        }
        if (bean.clss !== null && bean.clss !== undefined && bean.clss == "org.springframework.jmx.access.MBeanProxyFactoryBean") {
            for each(var prop in bean.propertyElements) {
                if (prop.name == "proxyInterface") {
                    var he = splitFullyQualifiedClsName(prop.value);
                    var beanClass = nameTable.getClassByName(he.ns, he.clsName, "java");
                    if (beanClass !== null && beanClass !== undefined && '[UnknownType]' != beanClass.getName()) {
                        beanClass.setLabel("JMXBean");
                    }
                }
            }
        }
    }

    // Spring Webflow
    //alert("WEBFLOW")
    //for each (var bean in spring_beans) {
    //    alert(bean.name + " == " + bean.clss);
    //}
    for each (var cfg in program.xml) {
        if (null == cfg.name() || null == cfg.name().localName.match("flow")) {
            continue;
        }
        var ns = new Namespace("http://www.springframework.org/schema/webflow");

        // Extract tainted(user-controlled) vars
        var taintedVars = [];
        for each (var j in cfg..ns::['input']) {
            var value = String(j["@value"]);
            if (value !== "") continue;
            var name= String(j["@name"]);
            if (name !== "") {
                name = name.replace(/[a-z]+Scope\./, '');
                if (taintedVars.indexOf(name) == -1) taintedVars.push(name);
            }
        }
        for each (var j in cfg..ns::['view-state']) {
            var model = String(j["@model"]);
            if (model !== "") {
                model = model.replace(/[a-z]+Scope\./, '');
                if (taintedVars.indexOf(model) == -1) taintedVars.push(model);
            }
        }
        for each (var j in cfg..ns::['set']) {
            var value = String(j["@value"]);
            var name = String(j["@name"]);
            if (value !== null && value.indexOf("requestParameters") > -1 && name !== "") {
                name = name.replace(/[a-z]+Scope\./, '');
                if (taintedVars.indexOf(name) == -1) taintedVars.push(name);
            }
        }
        taintedVars.push("currentUser.name")
        taintedVars.push("flowExecutionUrl")

        // Parse Expressions
        for each (var j in cfg..ns::['evaluate']) {
            var expression = String(j["@expression"]);
            group = expression.match(/(\w+)\.(\w+)\(([a-zA-Z0-9,. ]+)\)/)
            if (group === null) continue;
            if (group.length == 4) {
                var isEntrypoint = false;
                var bean_name = group[1];
                var method_name = group[2];
                var args = group[3].split(',');
                for each (var arg in args) {
                    arg = arg.trim();
                    arg = arg.replace(/[a-z]+Scope\./, '');
                    if (arg.indexOf("requestParameters")) isEntrypoint = true;
                    if (taintedVars.indexOf(arg)) isEntrypoint = true;
                }
                if (isEntrypoint) {
                    //alert("Adding entrypoint for " + bean_name + "." + method_name)
                    for each (var bean in spring_beans) {
                        if (bean !== null && bean.name == bean_name && bean.clss !== null) {
                            var klass = nameTable.getClassByFullName(bean.clss, "java");
                            if (klass !== null && klass !== undefined && klass.getName() != "[UnknownType]") {
                                var methods = klass.getMethods();
                                if (null != methods) {
                                    for each (var method in methods) {
                                        if (method.getName() == method_name) {
                                            //alert("Found method to mark as entrypoint " + method.getName());
                                            method.setLabel("SpringWebFlowEntrypoint");
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        // Consider vars as global fields and their setters as entrypoints
        // (This is not very accurate but it was working this way so lets keep it for now)
        for each (var j in cfg..ns::['var']) {
            //attribute will return 'xml' type, not a string.
            var vName = String(j["@class"]).trim();
            if (isSafeForJavaGlobal(vName)) {
                // isSafeForJavaGlobal() doesn't return true if the class is not found in the nameTable
                var klass = nameTable.getClassByFullName(vName, "java");
                klass.setLabel("WebFlowVar");
                dbg("Label WebFlowVar: " + vName);
            }

        }
    }

    program.spring_labeling_initialized = true;
}
if (null == program.spring_labeling_initialized) {
    dbg("java: INITIALIZING SPRING LABELING");
    initSpringLabeling();
} else {
    dbg("spring:  SPRING LABELING HAS ALREADY BEEN INITIALIZED OR THIS IS NOT AN ANDROID APP");
}

var MASS_ASSIGNMENT_REGEXP = /admin|role|access|price|cost|secret|priv/i;

// Function to extrac a list of values (sufices) from labels given a prefix
function extractLabelValues(obj, prefix) {
    var values = [];
    if (obj != null && prefix != null && prefix != "") {
        var labels = obj.getLabels();
        if (labels != null) {
            for each (var l in labels) {
                if (l.indexOf(prefix) == 0) {
                    var value = String(l.substring(prefix.length));
                    if (value != null && value.length > 0) {
                        values[values.length++] = value;
                    }

                }
            }
        }
    }
    return values;
}

function registerController(controller2commandclass, controllerClass, commandClass) {
    // Checks if command class is already present in the map, if so, it adds the controller class to the list for that command class
    if (controllerClass !== null && controllerClass.getName() != "[UnknownType]") {
        var ccname = commandClass.getPackageName() + "." + commandClass.getName();
        var controllerName = controllerClass.getPackageName() + "." + controllerClass.getName();
        var controller = {};
        controller.filename = "";
        try {
            controller.filename = String(controllerClass.getFileName());
        } catch (err) {
            var fields = controllerClass.getFields();
            if (fields !== null && fields !== undefined) {
                if (fields.length > 0 && fields[0] !== null && fields[0] !== undefined) controller.filename = String(fields[0].getFileName());
            }
        }
        if (controller.filename === undefined || controller.filename === null) controller.filename = "";
        controller.linenumber = 1;
        controller.name = String(controllerName);
        var controller_list = controller2commandclass[ccname];
        if (controller_list === null || controller_list === undefined) {
            controller2commandclass[ccname] = [controller];
        } else {
            controller_list[controller_list.length++] = controller;
            controller2commandclass[ccname] = controller_list;
        }
    }
}

function processField(field, visited, controllerClass) {
    // Loop through nested fields in the given class if they are not primitive of java JSD classes
    // If field name matches Mass Assignment regular expression, label it with exposedCommandField
    //Username, password, logged_in_status,
    var name = String(field.getName());
    var type = field.getType();
    var key = String(type.getPackageName() + "." + type.getName());
    if (name.match(MASS_ASSIGNMENT_REGEXP)) {
        field.setLabel("exposedCommandField");
    }
    if (!type.isPrimitive() && !key.match(/^(java|null).*/) && visited[key] != true) {
        visited[key] = true;
        var fields = type.getFields();
        if (fields != null) {
            registerController(controller2commandclass, controllerClass, type);
            for each (var new_field in fields) {
                var new_key = new_field.getType().getPackageName() + "." + new_field.getType().getName();
                if (visited[new_key] != true) {
                    processField(new_field, visited, controllerClass);
                }
            }
        }
    }
}

// Collect all Spring command classes
var sp2cc = nameTable.getClassesByLabel("spring2CommandObject", "java");
var sp3cc = nameTable.getClassesByLabel("spring3CommandObject", "java");
// This map will contain a list of command class and for each one a list of controllers that bind the command class without special configuration
var controller2commandclass = {};
var cmclasses = [];
if (sp2cc != null && sp2cc != undefined) for each (var c in sp2cc) cmclasses.push(c);
if (sp3cc != null && sp3cc != undefined) for each (var c in sp3cc) cmclasses.push(c);
if (cmclasses != null) {
    for each (var cmclass in cmclasses) {
        if (cmclass != null) {
            var labels = cmclass.getLabels();
            if (labels != null) {
                var insecureBinding = false;
                // Loop through command class labels and set insecureBinding to true if any label starts with that prefix
                for each (var label in labels) {
                    if (label.indexOf("insecureBinding") == 0) {
                        insecureBinding = true;
                        break;
                    }
                }
                if (insecureBinding) {
                    // If command class is bound insecurely, extract the controllers that fail to bind it securely from the labels
                    var controllerNames = extractLabelValues(cmclass, "insecureBinding~");
                    for each (var controllerName in controllerNames) {
                        var controllerClass = nameTable.getClassByFullName(controllerName, "java");
                        // Add the controller to the command class list in the controller2commandclass map
                        registerController(controller2commandclass, controllerClass, cmclass);
                        var visited = {};
                        visited[cmclass.getPackageName() + "." + cmclass.getName()] = true;
                        var fields = cmclass.getFields();
                        if (fields !== null && fields !== undefined) {
                            // Loop through the command class fields and look for other non primitive nor java classes nested in the object
                            for each (var field in fields) {
                                processField(field, visited, controllerClass);
                            }
                        }
                    }
                }
            }
        }
    }
}
if (null != controller2commandclass) {
    // Persist map fopr later usage
    persistObject("program.spring_controller2commandclass_map", controller2commandclass);
}

ScriptDefinitions.Script:
var visited = {};

// Spring MVC form fields / beans
