iterateOverFields(struts2PrivateInputs, "Struts2PrivateSource", visited);

visited = {};

                // Struts 2 hidden sources
                struts2HiddenInputs = nameTable.getFieldsByLabel("Struts2HiddenSource", "java");
                iterateOverFields(struts2HiddenInputs, "Struts2HiddenSource", visited);

                visited = {};

// Webflow input forms
