                      if (sourceEnclosingClass) {
                      var sourceEnclosingPackage = sourceEnclosingClass.getPackageName();
                      var sourceEnclosingMethodName = sourceEnclosingMethod.getName();
                      var sourceRuleID = sourceRule.getIdentifier();
                      sourceNode = sourceEnclosingPackage + "." + sourceEnclosingClass.getName();
                      if (sourceNode) {
                        // handle old JSP parser
                        if (-1 != sourceNode.search("_jsp")) {
                          var firstDot = sourceNode.indexOf(".");
