                          }
                          jspPath = jspPath.replace(/\./g,"/");           // convert package to path
                          jspPath = jspPath.replace(/\_/g,'.');           // correct _jsp extension
                          sourceNode = "/" + jspPath;
                        }
                        else if (null != sourceNode.match(/.*\.jsp$/)) {
                          // handling new JSP parser
                          var firstSlash = String(sourceEnclosingClass).indexOf("/");
                          if (firstSlash > 0) {
                            sourceNode = String(sourceEnclosingClass).substring(firstSlash); // remove JSP# generated by SCA
                          }
                        }

                        var seenURLs = new Array();
                        var seenURLs2 = new Array();
                        // add form reference to the finding as an external entry
                        for each (var b in jsfInputs) {
dbg("in first for each");
dbg("sourceNode: " + sourceNode);
dbg("ruleid: " + sourceRuleID);
dbg("functionname: " + sourceEnclosingMethodName);
                          if (b.clss !== undefined && b.clss == sourceNode) {
                            if (null != b.formid && null != b.filename && null != b.formlinenumber) {
                              //source rules this has to match deprecated with FV 3.11, so loop will only run prior to then.
                              if (b.setter == sourceEnclosingMethodName && (sourceRuleID == "4789D00C-133A-4540-BE9C-F192361625980" || sourceRuleID == "6B71322F-D088-410F-814F-59EC3049EE880")) {
                                for each (var url in b.urls) {
                                  if (!seenURLs[url]) {
                                    v.addExternalEntry(b.formid + "HTML Form ", url, b.filename, b.formlinenumber);
                                    seenURLs[url] = true;
                                  }
                                }
                              }
                            }
                          }

                          // add source result URL to the finding as an external entry
                          if (b.to === undefined || b.to === null) continue;
                          for (var i = 0; i < LOOP_LIMITER && i < b.to.length; i++){
                            var r = b.to[i];
dbg("in second for each: " + r + ", " + sourceNode);
                            //if (r == sourceNode)                         // jspPath
                            if (-1 != sourceNode.indexOf(r)) {
                              if (!seenURLs2[r]) {
                                v.addExternalEntry("Result", r);
                                seenURLs2[r] = true;
                              }
                            }
                          }
                        }
                        }
                      }
                    }

                    // primary file matching
                    if (v.getPrimaryFile() === null) continue;
                    var primaryFile = String(v.getPrimaryFile()).replace(/\\/g, "/");
                    //check if it's a valid file type that could be a view and thus mapped to a URL in JSF
                    if (!isUrlMappable(primaryFile)) continue;
                    var seenURLs = new Array();
                    var seenURLs2 = new Array();
                    for each (var b in jsfInputs) {
                      // add sink URL to the finding as an external entry
                      // line below should prevent NPE in for loop condition
                      if (b.to !== undefined && b.to !== null){
                        //limit to 5, for performance reasons
                        for (var i = 0; i < LOOP_LIMITER && i < b.to.length; i++){
                          var r = b.to[i];
dbg("in third for each");
dbg("new result: " + r);
dbg("primary file: " + primaryFile);
                          if (-1 != primaryFile.indexOf(r)) {
                            for each (var url in b.urls) {
                              if (!seenURLs[url]) {
                                v.addExternalEntry("Result", url);
                                seenURLs[url] = true;
