                      var b_filename = String(b.filename).replace(/\\/g, "/");
                      //don't cause a NPE in for loop condition
                      if (b.urls === undefined || b.urls === null) continue;
                      for (var j = 0; j < LOOP_LIMITER && j < b.urls.length; j++){
                        var url = b.urls[j];
dbg("in fourth for-each: " + primaryFile + " " + b_filename);
                        if (null != b.filename && -1 != primaryFile.indexOf(b_filename) && null != b.formid && null != b.formlinenumber && !seenURLs2[url]) {
                          v.addExternalEntry(b.formid + "HTML Form", url, b_filename, b.formlinenumber);
