        /**
         * check to see if a file contains a valid extension or not such that it could be mapped to a URL. Has to be some type of HTML-like file in order to be a view that could be mapped.
         */
        function isUrlMappable(filename){
            var validExtensions = ['html', '.jsp', '.tag', '.tagx', '.jspx', '.jsff', '.faces', '.ctp', '.htm', '.cfml', '.cfc', '.asp', '.vbscript', '.as', '.mxml', '.erb'];
            for (var extension in validExtensions){
                if (endsWith(filename, extension)){
                    return true;
                }
            }
            return false;
        }

        // This script has to be versioned 3.10 because it uses loadPersistedObject(...) and addExternalEntry(...) with 2 parameters instead of 4
        var numEntries = 0;
        var numSinks = 0;
        var numForms = 0;
        var strutsActions = loadPersistedObject("program.struts_actions");
        var vulns = getVulnerabilities();
        if (null != strutsActions) {
          for each (var v in vulns) {
dbg("in main for each: " + v);
        try {
          // match dataflow sources
          if(v) {
dbg("inf if(v)");
            var sourceEnclosingMethod = v.getSourceEnclosingFunction();
            if (sourceEnclosingMethod) {
              var sourceNode = null;
              var jspPath = null;
              var sourceEnclosingClass = sourceEnclosingMethod.getEnclosingClass();
              if (sourceEnclosingClass) {
                var sourceEnclosingPackage = sourceEnclosingClass.getPackageName();
                sourceNode = sourceEnclosingPackage + "." + sourceEnclosingClass.getName();
dbg("sourceNode package: " + sourceEnclosingPackage);
dbg("sourceNode class: " + sourceEnclosingClass);
dbg("sourceNode before: " + sourceNode);
                if (sourceNode) {
              // handling old JSP parser
              if (-1 != sourceNode.search("_jsp")) {
                var firstDot = sourceNode.indexOf(".");
                if (firstDot > 0) {
                  jspPath = sourceNode.substring(firstDot + 1); // remove package## generated by SCA
                }
                jspPath = jspPath.replace(/\./g,"/");           // convert package to path
                jspPath = jspPath.replace(/\_/g,'.');           // correct _jsp extension
                sourceNode = "/" + jspPath;
              }
              else if (null != sourceNode.match(/.*\.jsp$/)) {
                // handling new JSP parser
                var firstSlash = String(sourceEnclosingClass).indexOf("/");
                if (firstSlash > 0) {
                  sourceNode = String(sourceEnclosingClass).substring(firstSlash); // remove JSP# generated by SCA
                }
              }

dbg("sourceNode after: " + sourceNode);
              // add source action URL to the finding as an external entry
              for each (var a in strutsActions) {
dbg("in first for each");
                if (a.clss == sourceNode) {
                  for each (var actionURL in a.actionURLs) {
                    v.addExternalEntry("Action", actionURL);
                  }
                }

                // add source result URL to the finding as an external entry
                for each (var r in a.actionResults) {
dbg("in second for each");
                  if (r == sourceNode) {                        // jspPath
                    if (null != r && 0 != r.length) {
                  v.addExternalEntry("Result", r);
                    }
                  }
                }
              }
                }
              }
            }

            // primary file matching
            if (v.getPrimaryFile() === null) continue;
            var primaryFile = String(v.getPrimaryFile()).replace(/\\/g, "/");
            for each (var a in strutsActions) {
              // add sink action URL to the finding as an external entry
              for each (var r in a.actionResults) {
dbg("in third for each");
dbg("new result: " + r);
dbg("primary file: " + primaryFile);
            if (-1 != primaryFile.indexOf(r)) {
                  for each (var actionURL in a.actionURLs) {
                v.addExternalEntry("Result", actionURL);
              }
            }
              }

              // add sink result URL to the finding as an external entry
              for each (var f in a.actionForms) {
dbg("in fourth for each");
            if (0 != a.actionURLs.length && null != f.filename && -1 != primaryFile.indexOf(f.filename) && null != f.formid && null != f.formlinenumber) {
              for each (var actionURL in a.actionURLs) {
                v.addExternalEntry(f.formid + "HTML Form", actionURL, f.filename, f.formlinenumber);
              }
            }
              }
            }
          } // close if(v)
        }   // close try
        catch (err) {
            // actively ignoring XML parsing errors. Not much help to customers. See bug 31939 for more details.  
            // log(err);
        }
          } // close for(v)
